local config = {
  ui_story_32240401_1_dialog_content = "Saya di sini dan saya siap untuk pergi, jadi bisa kita pergi sekarang?",
  ui_story_32240401_2_dialog_content = "Sepertinya hari ini kamu lebih bersemangat dari biasanya.",
  ui_story_32240401_3_dialog_content = "Tentu saja! Setiap kunjungan ke tempat baru dan asing selalu membawa berbagai pengalaman baru.",
  ui_story_32240401_4_dialog_content = "Belum lagi, ini akan menjadi kali pertama saya bekerja di luar Longzhou.",
  ui_story_32240401_5_dialog_content = "Anda membuat poin yang bagus, jadi ayo kita berangkat!",
  ui_story_32240401_6_dialog_content = "Jadi, ini adalah salah satu tujuan dari rute perdagangan Keluarga Lin.",
  ui_story_32240401_7_dialog_content = "Rasanya seperti di Longzhou!",
  ui_story_32240401_8_dialog_content = "Namun, bangunan di kejauhan dan bau jalanan sangat berbeda dari Kerajaan Ji.",
  ui_story_32240401_9_dialog_content = "Ah, aku ingin pergi menjelajahi tempat itu.",
  ui_story_32240401_10_option_content = "Bukankah kamu di sini untuk menangani fiendling?",
  ui_story_32240401_11_dialog_content = "Jelas, dong!",
  ui_story_32240401_12_option_content = "Kalau begitu, biarkan aku mengajakmu berkeliling!",
  ui_story_32240401_13_dialog_content = "Itu tidak bisa. Bagaimanapun, kita di sini untuk menangani fiendlings, ingat?",
  ui_story_32240401_14_dialog_content = "Sebagai pendeta, menyelesaikan masalah orang-orang disekitarku selalu menjadi prioritas utamaku.",
  ui_story_32240401_15_dialog_content = "Tapi setelah urusan dengan fiendlings selesai, saya pasti akan melihat-lihat sekitar kota dengan baik.",
  ui_story_32240401_16_dialog_content = "Klien bilang seharusnya ada di sekitar sini...",
  ui_story_32240401_17_dialog_content = "<size=45>Maafkan saya, tapi apakah Anda Master Luo Song? Anda datang tepat waktu—</size>",
  ui_story_32240401_18_dialog_content = "Oh, aku tidak akan menyebut diriku sebagai master... Aku hanya pendeta pengembara, tidak lebih.",
  ui_story_32240401_19_dialog_content = "Apakah Anda orang yang mempekerjakan saya untuk menangani seorang fiendling?",
  ui_story_32240401_20_dialog_content = "Ya, itu aku!!!",
  ui_story_32240401_21_dialog_content = "Sekarang setelah aku melihatmu dengan kedua mataku, aku bisa bilang kamu adalah pahlawan yang hebat meskipun usiamu masih muda!",
  ui_story_32240401_22_dialog_content = "Ada pekerjaan yang harus dilakukan, jadi mari kita lepaskan formalitasnya. Bisakah kamu membawa kami ke fiendling sekarang?",
  ui_story_32240401_23_dialog_content = "Ini adalah gudangku. Makhluk jahat itu bersembunyi di suatu tempat di sini...",
  ui_story_32240401_24_dialog_content = "Ahhh, bisnisku yang malang—",
  ui_story_32240401_25_dialog_content = "Hmm, gudang ini jelas tampak berhantu... Kira-kira kamu bisa menanganinya, Luo Song?",
  ui_story_32240401_26_dialog_content = "Tidak masalah. Saya bisa merasakan gerakan fiendling. Itu pola yang saya kenal.",
  ui_story_32240401_27_dialog_content = "Beritahu saya, apa yang telah fiendling lakukan di sini akhir-akhir ini?",
  ui_story_32240401_28_dialog_content = "Oh, dari mana saya harus memulai! Pekerja yang menakutkan, dinding yang rusak, meminta-minta makanan...",
  ui_story_32240401_29_dialog_content = "Bahkan ia memakan kiriman barang impor yang sangat berharga! Darahku mendidih hanya dengan memikirkannya!",
  ui_story_32240401_30_dialog_content = "Aku mengerti. Aku akan mencarinya, jadi dia bisa minta maaf dengan benar atas perilakunya.",
  ui_story_32240401_31_dialog_content = "Aku memiliki kepercayaan penuh pada kemampuanmu! Bagaimanapun, kamu telah tiba di Colossus Caelestite...",
  ui_story_32240401_32_dialog_content = "<size=33>Dia tidak mengenali kamu?</size>",
  ui_story_32240401_33_dialog_content = "<size=33>Ssst—Jangan bahas itu sekarang!</size>",
  ui_story_32240401_34_dialog_content = "Tapi saya harus menekankan bahwa Anda harus berhati-hati sepenuhnya.",
  ui_story_32240401_35_dialog_content = "Saya telah meminta bantuan para ahli dari seluruh Astra untuk ini. Para cendekiawan dari Lumopolis, \"pembersih\" dari Umbraton, dan bahkan True Order...",
  ui_story_32240401_36_dialog_content = "<size=33>... Jangan dengarkan dia. Dia sedang mengada-ada.</size>",
  ui_story_32240401_37_dialog_content = "<size=33>Oh? Ternyata dia tidak terlalu jujur juga.</size>",
  ui_story_32240401_38_dialog_content = "... Dalam hal apapun, binatang buas ini bukan ancaman kecil. Ini adalah binatang buas yang ganas dan membunuh!",
  ui_story_32240401_39_dialog_content = "Ehem... harap tenang saja.",
  ui_story_32240401_40_dialog_content = "Tidak ada iblis yang terlalu kuat untuk tinjuku.",
  ui_story_32240401_41_dialog_content = "Aku akan mengawasi dari sini dan menunggu sampai itu keluar.",
  ui_story_32240401_42_dialog_content = "Aku akan tinggal bersamamu.",
  ui_story_32240401_43_dialog_content = "Hmm, aku mencium fiendling. Sepertinya dia keluar!",
  ui_story_32240401_44_dialog_content = "... Aku juga menciumnya. Mungkin ini yang mengeluarkan aroma tertentu?",
  ui_story_32240401_45_dialog_content = "Ayo keluar! Sekarang hanya ada kita bertiga di sini!",
  ui_story_32240401_46_dialog_content = "Hohoho, Aurorian bodoh! Trik apa yang kalian sembunyikan kali ini?",
  ui_story_32240401_47_dialog_content = "Aku adalah Musang Abadi yang Agung. Simpan saja tipu dayamu dan berikan aku pizza tomat, steak panggang, dan beberapa nugget, dan aku akan menyelesaikan masalahmu!",
  ui_story_32240401_48_dialog_content = "Jadi kamu adalah fiendling yang telah menimbulkan masalah di sekitar sini?",
  ui_story_32240401_49_dialog_content = "Kamu hanya tupai kecil saja!",
  ui_story_32240401_50_dialog_content = "Siapa kamu untuk menilai saya?! Jaga bicaramu, manusia kurang ajar!",
  ui_story_32240401_51_dialog_content = "Sekarang bawakan aku makanan yang aku inginkan, dan mungkin saja aku akan membiarkan hidupmu yang menyedihkan ini!",
  ui_story_32240401_52_dialog_content = "Aku tidak punya barang itu, tapi aku bisa mentraktirmu sesuatu yang lain.",
  ui_story_32240401_53_dialog_content = "Sesuatu yang lain, katamu? Kau telah membangkitkan rasa penasaranku, sekarang serahkan!",
  ui_story_32240401_54_dialog_content = "<size=45>Kamu yang minta! Satu sandwich buku jari, segera datang!</size>",
  ui_story_32240401_55_dialog_content = "Kamu—! Beraninya kamu memandang rendah padaku seperti ini!",
  ui_story_32240401_56_dialog_content = "Aku akan memberimu pelajaran yang tidak akan segera kau lupakan, manusia fana!",
  ui_story_32240401_57_dialog_content = "Itu seharusnya kalimatku, tikus kecil.",
  ui_story_32240401_58_dialog_content = "Karena merusak bisnis orang ini dengan ulahmu dan memakan barang dagangannya, aku tidak akan menunjukkan belas kasihan padamu!",
  ui_story_32240401_59_dialog_content = "Bah! Apa bedanya jika aku memakan beberapa barang curiannya? Dialah yang mempertaruhkan mata pencahariannya sendiri!",
  ui_story_32240401_60_dialog_content = "Daripada membiarkannya mendapatkan uang kotor dari barang-barang ini, lebih baik aku saja yang mengambilnya untuk diriku sendiri!",
  ui_story_32240401_61_dialog_content = "Rasakan ini!",
  ui_story_32240401_62_dialog_content = "Cepat sekali! Begitu rupanya... Sepertinya fiendling ini memang memiliki latihan setelah semua.",
  ui_story_32240401_63_dialog_content = "Jadi kamu menghindari seranganku... Tapi bagaimana dengan yang ini?!",
  ui_story_32240401_64_dialog_content = "Aku hampir tidak bisa mengikuti gerakannya... Ini adalah seekor weasel yang menakutkan!",
  ui_story_32240401_65_dialog_content = "Kamu tidak bisa terus begini selamanya, Nak!",
  ui_story_32240401_66_dialog_content = "Tidak, tapi aku tidak harus!",
  ui_story_32240401_67_dialog_content = "Astaga—?!",
  ui_story_32240401_68_dialog_content = "B-Beraninya kau menangkapku dari ekor abadiku! Lepaskan aku!",
  ui_story_32240401_69_dialog_content = "Tidak... Ini sudah berakhir. Bunuh aku atau biarkan aku, pilihan ada di tanganmu.",
  ui_story_32240401_70_dialog_content = "Harus kukatakan, kekuatan dan teknikmu hampir menakutkan kuat.",
  ui_story_32240401_71_dialog_content = "Mengapa kamu datang jauh-jauh hanya untuk membuat masalah?",
  ui_story_32240401_72_dialog_content = "Hmph, memuji saya ketika hidup saya sudah ada di tanganmu? Sekarang siapa tikus di kandang ayam?",
  ui_story_32240401_73_dialog_content = "Itu masih akan menjadi kamu, saya percaya.",
  ui_story_32240401_74_dialog_content = "Dalam hal apapun, saya benar-benar berpikir bahwa kekuatanmu sangat mengesankan, dan kamu bahkan bisa berkomunikasi dengan Aurorian dengan begitu jelas...",
  ui_story_32240401_75_dialog_content = "Seorang yang berbakat seperti dirimu pasti akan sangat sukses di Longzhou.",
  ui_story_32240401_76_dialog_content = "T-Tidak sebaik yang kamu pikirkan.",
  ui_story_32240401_77_dialog_content = "Ahem... Aku akan mengakui, aku adalah penguasa hutan kecil di Longzhou, tetapi itu hampir tidak dihitung sebagai kehidupan yang sukses.",
  ui_story_32240401_78_dialog_content = "Kamu tahu sebaik saya bahwa di Longzhou, fiendlings tidak hanya harus terlihat seperti Aurorian untuk diterima...",
  ui_story_32240401_79_dialog_content = "Mereka juga harus mempelajari aturan dan tata krama mereka.",
  ui_story_32240401_80_dialog_content = "Jika tidak, kita hanya dilihat sebagai binatang buas. Tidak peduli seberapa berbakat kita, mereka akan selalu menolak kita kesempatan untuk hidup yang lebih baik!",
  ui_story_32240401_81_dialog_content = "Tapi saya menolak untuk menerima itu. Siapa mereka untuk menentukan identitas kita, atau memberi label kita sebagai binatang liar?",
  ui_story_32240401_82_dialog_content = "Jadi secara alami, saya lebih dari senang untuk menghadapi laut dan menemukan rumah baru untuk diri saya sendiri, tempat di mana saya bisa hidup lebih bebas...",
  ui_story_32240401_83_dialog_content = "Tapi bayangkan kejutan saya ketika saya menemukan lebih banyak lagi Aurorian yang tinggal di sisi lain samudra! Saya benar-benar marah!",
  ui_story_32240401_84_dialog_content = "Semua Aurorian adalah sampah!",
  ui_story_32240401_85_dialog_content = "Haha, aku pikir kamu sudah bicara cukup.",
  ui_story_32240401_86_dialog_content = "Aurorian-lah yang bertanggung jawab membuat makanan yang sangat kamu sukai, lho, seperti pizza tomat, steak panggang, dan nugget!",
  ui_story_32240401_87_dialog_content = "S-Steak goreng...",
  ui_story_32240401_88_dialog_content = "Lihat betapa bersemangatnya kamu saat seseorang menyebutkan makanan! Itu menunjukkan bahwa kamu sama sekali bukan makhluk jahat...",
  ui_story_32240401_89_dialog_content = "Jadi, kenapa tidak ikut denganku dan berlatih di sisiku?",
  ui_story_32240401_90_dialog_content = "Berlatih? Dengan kamu?",
  ui_story_32240401_91_dialog_content = "Benar. Aku adalah pendeta pengembara, dan saat ini aku sedang dalam proses mengasah kemampuanku.",
  ui_story_32240401_92_dialog_content = "Saya juga bepergian dengan banyak fiendling seperti dirimu, dan masing-masing memiliki alasan sendiri untuk berlatih.",
  ui_story_32240401_93_dialog_content = "Tetap bersamaku, dan kamu akan bertemu dengan berbagai Aurorian yang jujur yang dapat menunjukkanmu jalan menuju kehidupan yang lebih baik.",
  ui_story_32240401_94_dialog_content = "Kamu serius? Lalu... Biarkan aku bergabung denganmu!",
  ui_story_32240401_95_dialog_content = "Bagus, jawaban yang bagus dan cepat! Aku sudah mulai menyukaimu.",
  ui_story_32240401_96_dialog_content = "Tapi, sebelum aku melakukannya... Bolehkah aku minta tolong?",
  ui_story_32240401_97_dialog_content = "Ada apa?",
  ui_story_32240401_98_dialog_content = "Bisakah kamu mentraktirku pizza tomat? Dan mungkin juga steak panggangan dan nugget?",
  ui_story_32240401_99_dialog_content = "Sejak saya tiba, saya telah mendengar banyak tentang itu tetapi belum mencoba satupun!",
  ui_story_32240401_100_dialog_content = "Dan gudang pemilik toko ini hanya menyimpan barang-barang cacat yang hanya bisa digunakan sekali!",
  ui_story_32240401_101_dialog_content = "Hanya itu yang kamu inginkan? Dan di sini saya pikir kamu akan meminta sesuatu yang serius.",
  ui_story_32240401_102_dialog_content = "Kamu punya kesepakatan sendiri, temanku. Setelah aku selesai berurusan dengan pemilik gudang ini...",
  ui_story_32240401_103_dialog_content = "Saya akan menggunakan uang itu untuk mengajakmu makan pesta Aurorian buatan rumah yang jujur!",
  ui_story_32240401_104_dialog_content = "B-Benarkah...? Ahem, maka dari hari ini, kamu akan menjadi temanku... Tidak, majikanku! Terima kasih!",
  ui_story_32240401_105_dialog_content = "Ayo, PlayerName.",
  ui_story_32240401_106_dialog_content = "Anda tidak keberatan memiliki satu pendengar lagi saat Anda memperkenalkan Twin Pavilions Bay, bukan?"
}
return config
